import{_ as d,o as r,c as e,a0 as s}from"./chunks/framework.DQOulFGV.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"web/other/restful.md","filePath":"web/other/restful.md","lastUpdated":1571823146000}'),a={name:"web/other/restful.md"};function l(o,t,n,i,p,g){return r(),e("div",null,[...t[0]||(t[0]=[s('<h3 id="restful接口风格" tabindex="-1">Restful接口风格 <a class="header-anchor" href="#restful接口风格" aria-label="Permalink to &quot;Restful接口风格&quot;">​</a></h3><p>一、什么是Restful风格</p><p>REST是REpresentational State Transfer的缩写（一般中文翻译为表述性状态转移），REST 是一种体系结构，而 HTTP 是一种包含了 REST 架构属性的协议。 简单地说，REST 就是将资源的状态以适合客户端或服务端的形式从服务端转移到客户端（或者反过来）。在 REST 中，资源通过 URL 进行识别和定位，然后通过行为(即 HTTP 方法)来定义 REST 来完成怎样的功能。</p><p>二、范例说明</p><table tabindex="0"><thead><tr><th>CRUD 动作</th><th>HTTP 方法</th></tr></thead><tbody><tr><td>Create</td><td>POST</td></tr><tr><td>Read</td><td>GET</td></tr><tr><td>Update</td><td>PUT 或 PATCH</td></tr><tr><td>Delete</td><td>DELETE</td></tr></tbody></table><p>上表简单表述了Http的各种方法对应的CRUD动作，我们以“用户-文章-回复”这样的模型来举例说明Restful风格的url应该怎样设计。</p><ol><li>新增数据</li></ol><p><strong>传统风格url</strong>：<br> 新增用户的页面，get请求</p><p><strong>/addUser</strong> <br> 实际新增用户的业务逻辑，post请求</p><p><strong>/doAddUser</strong> <br> Restful风格url： 新增用户的页面，get请求</p><p><strong>/users/new</strong> <br> 新增用户的业务逻辑，post请求</p><p><strong>/users</strong> <br> 优劣对比：乍一看两者差不多，反而Restful风格的url有点迷糊，不能直接看出想干什么。</p><ol start="2"><li>读取数据</li></ol><p><strong>传统风格url</strong>：<br> 获得用户信息，get请求</p><p><strong>/getUser?id=1</strong> <br> 获取用户列表，get请求</p><p><strong>/getUserList</strong> <br> Restful风格url： 获得用户信息，get请求</p><p><strong>/users/1</strong> <br> 获取用户列表，get请求</p><p><strong>/users</strong> <br> 优劣对比：感觉都可以，Restful风格的url好像长度更短些</p><ol start="3"><li>更新数据</li></ol><p>传统风格url：</p><p><strong>进入更新用户的页面，get请求</strong> <br> /updateUser?id=1</p><p><strong>实际处理更新用户信息的操作，post请求</strong> <br> /doUpdateUser?id=1</p><p><strong>Restful风格url</strong>：<br> 进入更新用户的页面，get请求 /users/1/edit</p><p><strong>实际处理更新用户信息的操作，put请求</strong> <br> /users/1</p><ol start="4"><li>删除数据</li></ol><p>传统风格url：</p><p><strong>删除用户，get请求</strong> <br> /deleteUser?id=1</p><p><strong>Restful风格url</strong>：<br> 删除用户，delete请求 /users/1</p><ol start="5"><li>优劣对比</li></ol><p>单一业务这样看起来Restful风格并没有明显的好处，下面我们把这些放在一起看，再加点复杂的动作。</p><h4 id="传统风格" tabindex="-1">传统风格： <a class="header-anchor" href="#传统风格" aria-label="Permalink to &quot;传统风格：&quot;">​</a></h4><table tabindex="0"><thead><tr><th>用户接口</th><th>请求方法</th><th>demo</th></tr></thead><tbody><tr><td>/user/getUserList</td><td>get</td><td>#用户列表</td></tr><tr><td>/user/getUser?id=1</td><td>get</td><td>#查询用户信息</td></tr><tr><td>/user/addUser</td><td>get</td><td>#新增用户页面</td></tr><tr><td>/user/doAddUser</td><td>post</td><td>#新增用户业务</td></tr><tr><td>/user/updateUser?id=1</td><td>get</td><td>#修改用户信息的页面</td></tr><tr><td>/user/doUpdateUser?id=1</td><td>post</td><td>#更新用户信息业务</td></tr><tr><td>/user/deleteUser?id=1</td><td>get</td><td>#删除用户信息</td></tr></tbody></table><table tabindex="0"><thead><tr><th>文章接口</th><th>请求方法</th><th>demo</th></tr></thead><tbody><tr><td>/article/getArticleList</td><td>get</td><td>#文章列表</td></tr><tr><td>/article/getArticle?id=1</td><td>get</td><td>#查询文章信息</td></tr><tr><td>/article/addArticle</td><td>get</td><td>#新增文章页面</td></tr><tr><td>/article/doAddArticle</td><td>post</td><td>#新增文章业务</td></tr><tr><td>/article/updateArticle?id=1</td><td>get</td><td>#修改文章信息的页面</td></tr><tr><td>/article/doUpdateArticle?id=1</td><td>post</td><td>#更新文章信息业务</td></tr><tr><td>/article/deleteArticle?id=1</td><td>get</td><td>#删除文章信息</td></tr><tr><td>/article/getArticleListByUser?userId=1</td><td>get</td><td>#查询用户下的文章</td></tr></tbody></table><table tabindex="0"><thead><tr><th>回复接口</th><th>请求方法</th><th>demo</th></tr></thead><tbody><tr><td>/answer/getAnswerList</td><td>get</td><td>#回复列表</td></tr><tr><td>/answer/getAnswer?id=1</td><td>get</td><td>#查询回复信息</td></tr><tr><td>/answer/addAnswer</td><td>get</td><td>#新增回复页面</td></tr><tr><td>/answer/doAddAnswer</td><td>post</td><td>#新增回复业务</td></tr><tr><td>/answer/updateAnswer?id=1</td><td>get</td><td>#修改回复信息的页面</td></tr><tr><td>/answer/doUpdateAnswer?id=1</td><td>post</td><td>#更新回复信息业务</td></tr><tr><td>/answer/deleteAnswer?id=1</td><td>get</td><td>#删除回复信息</td></tr><tr><td>/answer/getAnswerListByArtical?artId=1</td><td>get</td><td>#查询文章下的回复</td></tr></tbody></table><p>可以看出传统的url风格更多的以行为动作来命名（addXXX，updateXXX，...），url很长，看起来不美观。</p><h4 id="restful风格" tabindex="-1">Restful风格: <a class="header-anchor" href="#restful风格" aria-label="Permalink to &quot;Restful风格:&quot;">​</a></h4><table tabindex="0"><thead><tr><th>用户接口</th><th>请求方法</th><th>demo</th></tr></thead><tbody><tr><td>/users</td><td>get</td><td>#用户列表</td></tr><tr><td>/users/1</td><td>get</td><td>#查询用户信息</td></tr><tr><td>/users/new</td><td>get</td><td>#新增用户页面</td></tr><tr><td>/users</td><td>post</td><td>#新增用户业务</td></tr><tr><td>/users/1/edit</td><td>get</td><td>#修改用户页面</td></tr><tr><td>/users/1</td><td>put</td><td>#修改用户业务</td></tr><tr><td>/users/1</td><td>delete</td><td>#删除用户</td></tr></tbody></table><table tabindex="0"><thead><tr><th>文章接口</th><th>请求方法</th><th>demo</th></tr></thead><tbody><tr><td>/articles</td><td>get</td><td>#文章列表</td></tr><tr><td>/articles/1</td><td>get</td><td>#查询文章信息</td></tr><tr><td>/articles/new</td><td>get</td><td>#新增文章页面</td></tr><tr><td>/articles</td><td>post</td><td>#新增文章业务</td></tr><tr><td>/articles/1/edit</td><td>get</td><td>#修改文章页面</td></tr><tr><td>/articles/1</td><td>put</td><td>#修改文章业务</td></tr><tr><td>/articles/1</td><td>delete</td><td>#删除文章</td></tr><tr><td>/users/1/articles</td><td>get</td><td>#用户1的文章列表</td></tr></tbody></table><table tabindex="0"><thead><tr><th>回复接口</th><th>请求方法</th><th>demo</th></tr></thead><tbody><tr><td>/answers</td><td>get</td><td>#回复列表</td></tr><tr><td>/answers/1</td><td>get</td><td>#查询回复信息</td></tr><tr><td>/answers/new</td><td>get</td><td>#新增回复页面</td></tr><tr><td>/answers</td><td>post</td><td>#新增回复业务</td></tr><tr><td>/answers/1/edit</td><td>get</td><td>#修改回复页面</td></tr><tr><td>/answers/1</td><td>put</td><td>#修改回复业务</td></tr><tr><td>/answers/1</td><td>delete</td><td>#删除回复</td></tr><tr><td>/articles/1/answers</td><td>get</td><td>#文章1的回复列表</td></tr></tbody></table><p>Restful风格更多的以资源名和状态来命名url，且资源一般使用复数（少数情况用单数），url格式比较固定，使用不同的Http方法区分。</p>',40)])])}const b=d(a,[["render",l]]);export{h as __pageData,b as default};
